<?php
namespace App\Http\Controllers;
use App\Models\ContactEnquiry; use App\Models\Faq; use App\Models\Page; use App\Models\TeamMember; use Illuminate\Http\Request;
class PublicContentController extends Controller { public function faqs(Request $request){$q=Faq::with('service')->where('published',true)->orderBy('sort_order'); if($request->service_id)$q->where('service_id',$request->service_id); return $q->get();} public function team(){return TeamMember::where('published',true)->orderBy('sort_order')->get();} public function page(string $slug){return Page::where('published',true)->where(fn($q)=>$q->where('slug',$slug)->orWhere('slug_ar',$slug))->firstOrFail();} public function enquiry(Request $request){$data=$request->validate(['name'=>'required|string|max:120','email'=>'required|email','mobile'=>'nullable|string|max:30','service_id'=>'nullable|exists:services,id','preferred_language'=>'nullable|in:en,ar','subject'=>'nullable|string|max:180','message'=>'required|string|max:5000','source_page'=>'nullable|string|max:255','utm_parameters'=>'nullable|array']); return response()->json(ContactEnquiry::create($data),201);} }
